Register Health Facility Site.code:
// Create a site in a Resource Map collection.
submitSite(
  // 1) Collection ID.
  $.data.collectionId,
  // 2) The site.
  {
    name: 'Mwanza Health Centre',
    lat: -2.5164,
    lng: 32.9175,
    // Field values keyed by field code.
    properties: {
      facility_type: 'Health Centre',
      beds: 24,
      phone: '+255700000000',
    },
  }
);

Submit Site From Survey.code:
// Map a survey submission to a new site.
submitSite(
  // 1) Collection ID, from the credential or payload.
  $.data.collectionId,
  // 2) Site built from the submission.
  {
    name: $.data.water_point_name,
    lat: $.data.gps.latitude,
    lng: $.data.gps.longitude,
    properties: {
      functional: $.data.is_functional,
      source_type: $.data.source_type,
      last_visited: $.data.submission_date,
    },
  }
);

Submit Many Sites.code:
// Create one site per item in $.data.sites.
each(
  $.data.sites[*],
  submitSite(
    // 1) Collection ID.
    '303',
    // 2) Site data for the current item.
    {
      name: $.data.name,
      lat: $.data.lat,
      lng: $.data.lng,
      properties: $.data.properties,
    }
  )
);
